def transform(grid):
    h,w=len(grid),len(grid[0]); bg=max(set(sum(grid,[])), key=lambda c:sum(row.count(c) for row in grid))
    out=[r[:] for r in grid]
    seen=set()
    from collections import deque
    q=deque()
    for r in range(h):
        for c in (0,w-1):
            if grid[r][c]==bg and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if grid[r][c]==bg and (r,c) not in seen: seen.add((r,c)); q.append((r,c))
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==bg and (nr,nc) not in seen:
                seen.add((nr,nc)); q.append((nr,nc))
    for r in range(h):
        for c in range(w):
            if grid[r][c]==bg and (r,c) not in seen:
                # enclosed component; 2x2 cavities take color 2, others color 7
                comp={(r,c)}; stack=[(r,c)]
                while stack:
                    y,x=stack.pop()
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        yy,xx=y+dy,x+dx
                        if 0<=yy<h and 0<=xx<w and grid[yy][xx]==bg and (yy,xx) not in seen and (yy,xx) not in comp:
                            comp.add((yy,xx)); stack.append((yy,xx))
                color=2 if len(comp)==4 else 7
                for y,x in comp: out[y][x]=color
    return out
